// =====================================================================
// Normaliza os RFs recebidos do front e monta a consulta de bloqueio.
// Mode: Run Once for All Items
//
// Fonte da verdade em DUAS tabelas, com papeis distintos:
//   kvm4_db.rf_nota        -> "esse RF VIROU NOTA"   => BLOQUEADO
//   kvm4_db.rfs_faturados  -> "esse RF FOI ENVIADO"  => LEGADO (se nao houver nota)
// RF que nao aparecer em nenhuma das duas nao volta na resposta => NOVO.
//
// Tabelas QUALIFICADAS com o banco: a credencial MySQL do n8n pode ter
// outro schema como default.
// =====================================================================

const TB_NOTA  = 'kvm4_db.rf_nota';
const TB_ENVIO = 'kvm4_db.rfs_faturados';

const body   = $json.body ?? $json;
const tipo   = String(body.tipo_faturamento ?? 'VALE').trim();
const brutos = Array.isArray(body.rfs) ? body.rfs : [];

// Mesma normalizacao do front (conferencia_rf.normalizar_rf):
// string, sem espacos nas pontas, sem sufixo '.0' de float do Excel.
const normalizar = (v) => {
  if (v === null || v === undefined) return '';
  let t = String(v).trim();
  if (/^\d+\.0$/.test(t)) t = t.slice(0, -2);
  return t;
};

const rfs = [...new Set(brutos.map(normalizar).filter(Boolean))];

let sql = '';
if (rfs.length) {
  const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "''");
  const lista = rfs.map((r) => "'" + esc(r) + "'").join(',');

  // Ramo 1 = BLOQUEADO. Uma linha POR NOTA: substituicao (mesmo RF em 2
  // notas) devolve 2 linhas de proposito, para o front sinalizar.
  // Ramo 2 = LEGADO: enviado antes, mas sem nota vinculada.
  // CAST(NULL AS DATETIME) evita o UNION resolver a coluna como binaria e
  // truncar o enviado_em do ramo 2.
  sql =
    'SELECT n.rf AS rf, 1 AS bloqueado, n.nIdNf AS nIdNf,' +
    ' n.cNumNFSe AS numero_nota, n.cNumOs AS os, n.emp AS emp,' +
    " COALESCE(n.status_nota,'FATURADA') AS status_nota," +
    ' CAST(NULL AS DATETIME) AS enviado_em' +
    ' FROM ' + TB_NOTA + ' n WHERE n.rf IN (' + lista + ')' +
    ' UNION ALL ' +
    'SELECT f.rf, 0, NULL, NULL, NULL, NULL, NULL, f.enviado_em' +
    ' FROM ' + TB_ENVIO + ' f WHERE f.rf IN (' + lista + ')' +
    ' AND NOT EXISTS (SELECT 1 FROM ' + TB_NOTA + ' x WHERE x.rf = f.rf)' +
    ' ORDER BY rf, bloqueado DESC, nIdNf';
}

return [{ json: { tipo_faturamento: tipo, rfs: rfs, total_consultado: rfs.length, sql: sql } }];

// =====================================================================
// Monta a resposta que o front consome.
// Mode: Run Once for All Items
//
// A chave "existentes" e' mantida por RETROCOMPATIBILIDADE: um front antigo
// (sem a nocao de bloqueio) continua funcionando e trata tudo como duplicado.
// O campo "linha" tambem e' mantido -- e' o que o front antigo exibe como
// "Registro no banco". Aqui ele vira uma referencia legivel.
// =====================================================================

const itens = $input.all().map((i) => i.json).filter(function (j) {
  return j && j.rf !== undefined && j.rf !== null;
});

const existentes = itens.map(function (j) {
  const bloqueado = String(j.bloqueado) === '1' || j.bloqueado === true;

  if (bloqueado) {
    const nota = j.numero_nota == null ? '' : String(j.numero_nota);
    return {
      rf: String(j.rf),
      bloqueado: true,
      status_nota: j.status_nota == null ? 'FATURADA' : String(j.status_nota),
      numero_nota: nota || null,
      nIdNf: j.nIdNf == null ? null : Number(j.nIdNf),
      os: j.os == null ? null : String(j.os),
      emp: j.emp == null ? null : String(j.emp),
      legado: false,
      enviado_em: null,
      // referencia legivel (front antigo mostra isso como "Registro no banco")
      linha: 'NF ' + (nota || '?') + ' / ' + (j.status_nota || 'FATURADA'),
    };
  }

  const env = j.enviado_em == null ? null : String(j.enviado_em);
  return {
    rf: String(j.rf),
    bloqueado: false,
    status_nota: null,
    numero_nota: null,
    nIdNf: null,
    os: null,
    emp: null,
    legado: true,
    enviado_em: env,
    linha: env ? 'enviado em ' + env + ' (sem nota)' : 'enviado antes (sem nota)',
  };
});

// Substituicao: o MESMO rf voltando em 2+ linhas bloqueadas.
const vezes = {};
for (const e of existentes) {
  if (e.bloqueado) vezes[e.rf] = (vezes[e.rf] || 0) + 1;
}
for (const e of existentes) {
  if (e.bloqueado && vezes[e.rf] > 1) e.substituicao = true;
}

const bloqueados = existentes.filter(function (e) { return e.bloqueado; });
const legado = existentes.filter(function (e) { return !e.bloqueado; });

console.log('bloqueados: ' + bloqueados.length + ' | legado: ' + legado.length);

return [{
  json: {
    existentes: existentes,
    resumo: {
      bloqueados: bloqueados.length,
      rfs_bloqueados: [...new Set(bloqueados.map(function (e) { return e.rf; }))].length,
      legado: legado.length,
      com_substituicao: bloqueados.filter(function (e) { return e.substituicao; }).length,
    },
  },
}];
